import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { Calendar, Check, X, Plus, RefreshCw } from 'lucide-react';
import axios from 'axios';
import toast from 'react-hot-toast';

const DailyTracker = () => {
    const { user, token } = useAuth();
    const [tasks, setTasks] = useState([]);
    const [selectedDay, setSelectedDay] = useState(null);
    const [loading, setLoading] = useState(true);
    const [creating, setCreating] = useState(false);

    useEffect(() => {
        if (user) {
            fetchTasks();
        }
    }, [user]);

    const fetchTasks = async () => {
        try {
            const response = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(response.data);
            setLoading(false);
        } catch (error) {
            console.error('Failed to fetch tasks:', error);
            toast.error('Failed to load tasks');
            setLoading(false);
        }
    };

    const createTaskForDay = async (day) => {
        setCreating(true);
        try {
            const date = new Date(2026, 6, day);
            const dateStr = date.toISOString().split('T')[0];
            
            const response = await axios.post(
                `http://localhost:8081/api/tasks/user/${user.id}/day/${day}?date=${dateStr}`,
                {},
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks([...tasks, response.data]);
            toast.success(`Tasks created for Day ${day}`);
            return response.data;
        } catch (error) {
            console.error('Failed to create task:', error);
            toast.error('Failed to create tasks');
            return null;
        } finally {
            setCreating(false);
        }
    };

    const toggleTask = async (taskId, field) => {
        const task = tasks.find(t => t.id === taskId);
        if (!task) return;

        const updatedTask = { ...task, [field]: !task[field] };
        
        try {
            const response = await axios.put(
                `http://localhost:8081/api/tasks/${taskId}`,
                updatedTask,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(tasks.map(t => t.id === taskId ? response.data : t));
        } catch (error) {
            toast.error('Failed to update task');
        }
    };

    const handleDayClick = async (day) => {
        setSelectedDay(day);
        const dayTasks = tasks.filter(task => task.day === day);
        if (dayTasks.length === 0 && !creating) {
            await createTaskForDay(day);
        }
    };

    const getDayTasks = (day) => tasks.filter(task => task.day === day);

    const getDayStatus = (day) => {
        const dayTasks = getDayTasks(day);
        if (dayTasks.length === 0) return 'empty';
        const completed = dayTasks.filter(t => t.overallCompleted).length;
        if (completed === dayTasks.length) return 'done';
        if (completed > 0) return 'partial';
        return 'started';
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
            </div>
        );
    }

    const taskLabels = [
        { key: 'javaCompleted', label: '☕ Java (1.5h)' },
        { key: 'leetcodeCompleted', label: '💻 LeetCode (1+)' },
        { key: 'dsaCompleted', label: '📊 DSA/OOP (1h)' },
        { key: 'sqlCompleted', label: '🗄️ SQL/APIs (1h)' },
        { key: 'projectCompleted', label: '🚀 Project (2-3h)' },
        { key: 'githubCompleted', label: '📁 GitHub/Portfolio' }
    ];

    const calendarDays = [];
    for (let day = 1; day <= 31; day++) {
        calendarDays.push(day);
    }

    const weekDays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

    return (
        <div className="max-w-7xl mx-auto">
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
                <div className="flex items-center justify-between mb-6">
                    <div className="flex items-center gap-3">
                        <Calendar size={28} className="text-blue-600" />
                        <h1 className="text-2xl font-bold text-gray-800">July 2026</h1>
                    </div>
                    <button 
                        onClick={fetchTasks}
                        className="flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700"
                    >
                        <RefreshCw size={16} />
                        Refresh
                    </button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Calendar */}
                    <div className="lg:col-span-2">
                        <div className="grid grid-cols-7 gap-1.5">
                            {weekDays.map(day => (
                                <div key={day} className="text-center text-xs font-medium text-gray-500 py-1">
                                    {day}
                                </div>
                            ))}
                            {calendarDays.map((day) => {
                                const status = getDayStatus(day);
                                let bgColor = 'bg-gray-50 hover:bg-gray-100';
                                let textColor = 'text-gray-600';
                                
                                if (status === 'done') {
                                    bgColor = 'bg-green-500 hover:bg-green-600';
                                    textColor = 'text-white';
                                } else if (status === 'partial') {
                                    bgColor = 'bg-yellow-400 hover:bg-yellow-500';
                                    textColor = 'text-white';
                                } else if (status === 'started') {
                                    bgColor = 'bg-blue-200 hover:bg-blue-300';
                                    textColor = 'text-gray-700';
                                }
                                
                                const isSelected = selectedDay === day;
                                
                                return (
                                    <button
                                        key={day}
                                        onClick={() => handleDayClick(day)}
                                        className={`aspect-square rounded-lg flex items-center justify-center text-sm font-medium transition-all ${bgColor} ${textColor} ${isSelected ? 'ring-2 ring-blue-500 ring-offset-2' : ''}`}
                                    >
                                        {day}
                                    </button>
                                );
                            })}
                        </div>

                        <div className="flex items-center gap-4 mt-4 text-xs text-gray-500">
                            <div className="flex items-center gap-1.5">
                                <div className="w-3 h-3 bg-green-500 rounded"></div>
                                <span>Done</span>
                            </div>
                            <div className="flex items-center gap-1.5">
                                <div className="w-3 h-3 bg-yellow-400 rounded"></div>
                                <span>Partial</span>
                            </div>
                            <div className="flex items-center gap-1.5">
                                <div className="w-3 h-3 bg-blue-200 rounded"></div>
                                <span>Started</span>
                            </div>
                            <div className="flex items-center gap-1.5">
                                <div className="w-3 h-3 bg-gray-50 border border-gray-200 rounded"></div>
                                <span>Empty</span>
                            </div>
                        </div>
                    </div>

                    {/* Task List */}
                    <div className="bg-gray-50 rounded-xl p-4">
                        <h3 className="font-semibold text-gray-800 mb-3">
                            {selectedDay ? `Day ${selectedDay} Tasks` : 'Select a day'}
                        </h3>
                        
                        {selectedDay ? (
                            <div className="space-y-2">
                                {taskLabels.map(({ key, label }) => {
                                    const dayTasks = getDayTasks(selectedDay);
                                    const task = dayTasks[0];
                                    const isCompleted = task ? task[key] : false;
                                    
                                    return (
                                        <div
                                            key={key}
                                            onClick={() => task && toggleTask(task.id, key)}
                                            className={`flex items-center justify-between p-3 bg-white rounded-lg cursor-pointer transition-all hover:shadow-sm ${isCompleted ? 'border-l-4 border-green-500' : 'border-l-4 border-gray-300'}`}
                                        >
                                            <span className={`text-sm ${isCompleted ? 'text-gray-400 line-through' : 'text-gray-700'}`}>
                                                {label}
                                            </span>
                                            <div className={`w-6 h-6 rounded-full flex items-center justify-center ${isCompleted ? 'bg-green-500 text-white' : 'bg-gray-200 text-gray-500'}`}>
                                                {isCompleted ? <Check size={14} /> : <X size={14} />}
                                            </div>
                                        </div>
                                    );
                                })}
                                
                                {getDayTasks(selectedDay).length === 0 && !creating && (
                                    <div className="text-center py-8">
                                        <p className="text-gray-500 text-sm mb-3">No tasks for this day</p>
                                        <button
                                            onClick={() => handleDayClick(selectedDay)}
                                            className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm hover:bg-blue-700 transition flex items-center gap-2 mx-auto"
                                        >
                                            <Plus size={16} />
                                            Create Tasks
                                        </button>
                                    </div>
                                )}
                                
                                {creating && (
                                    <div className="text-center py-8">
                                        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto"></div>
                                        <p className="text-gray-500 text-sm mt-2">Creating tasks...</p>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <div className="flex items-center justify-center h-48 text-gray-400 text-sm">
                                Click a day on the calendar
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default DailyTracker;
